function removeDuplicatesWithSet(nums) {
  const unique = [...new Set(nums)];     // keeps first-seen order, already sorted
  for (let i = 0; i < unique.length; i++) nums[i] = unique[i];
  return unique.length;
}

function removeDuplicates(nums) {
  if (nums.length === 0) return 0;
  let write = 1;                      // nums[0] is always kept
  for (let read = 1; read < nums.length; read++) {
    if (nums[read] !== nums[write - 1]) {
      nums[write] = nums[read];
      write++;
    }
  }
  return write;
}

def remove_duplicates(nums):
    if not nums:
        return 0
    write = 1                           # nums[0] is always kept
    for read in range(1, len(nums)):
        if nums[read] != nums[write - 1]:
            nums[write] = nums[read]
            write += 1
    return write

class Solution {
    public int removeDuplicates(int[] nums) {
        if (nums.length == 0) return 0;
        int write = 1;                  // nums[0] is always kept
        for (int read = 1; read < nums.length; read++) {
            if (nums[read] != nums[write - 1]) {
                nums[write] = nums[read];
                write++;
            }
        }
        return write;
    }
}

